#!/usr/bin/env python3
"""Apply reviewed line edits only to their exact preimage; delete this one-shot helper.
The payload is compressed JSON: repository path -> SHA256 and line replacements.
No source is written until every original and every edit interval is verified.
"""
from pathlib import Path
import base64, hashlib, json, zlib
ROOT = Path(__file__).resolve().parents[2]
PAYLOAD = ''''''
# Correct transcription of the two fixed base64 segments, before decompression.
PAYLOAD = PAYLOAD.replace('TTRYtfWbJmGhu0', 'TTRYtfWbGhu0').replace('JOsgUU7Pzh', 'JOsgU7Pzh')
changes = json.loads(zlib.decompress(base64.b64decode(PAYLOAD)))
planned = []
for name, spec in changes.items():
    path = (ROOT / name).resolve()
    if not path.is_relative_to(ROOT): raise SystemExit('path outside checkout')
    raw = path.read_bytes()
    if hashlib.sha256(raw).hexdigest() != spec['sha256']: raise SystemExit(f'source drift: {name}')
    lines = raw.decode('utf-8').splitlines(keepends=True)
    previous = len(lines) + 1
    for start, end, replacement in reversed(spec['edits']):
        if not 0 <= start <= end < previous: raise SystemExit(f'invalid edit: {name}')
        lines[start:end] = [replacement]
        previous = start + 1
    planned.append((path, ''.join(lines)))
for path, content in planned:
    path.write_text(content, encoding='utf-8')
    print('wired', path.relative_to(ROOT))
Path(__file__).unlink()
